struct mm_struct *init_new_context(struct task_struct *p, struct user_namespace *user_ns) {
    struct mm_struct *mm = (struct mm_struct *)kmalloc(sizeof(struct mm_struct), GFP_KERNEL);
    if (!mm)
        return NULL;

    mm->mmap = NULL;
    mm->mmap_cache = NULL;
    mm->get_unmapped_area = arch_get_unmapped_area;
    mm->unmap_area = arch_unmap_area;
    atomic_set(&mm->mm_users, 1);
    atomic_set(&mm->mm_count, 1);
    mm->task_size = TASK_SIZE;
    mm->highest_vm_end = PAGE_SIZE;

    if (!mm_alloc_pgd(mm)) {
        kfree(mm);
        return NULL;
    }

    spin_lock_init(&mm->page_table_lock);
    spin_lock_init(&mm->mmlist_lock);

    if (current->mm) {
        mm->flags = current->mm->flags;
        mm->def_flags = current->mm->def_flags;
        mm->context = current->mm->context;
    } else {
        mm->flags = 0;
        mm->def_flags = 0;
        mm->context = NULL;
    }

    if (IS_ERR(mm->context)) {
        kfree(mm);
        return NULL;
    }

    return mm;
}

struct mm_struct *init_mm(struct mm_struct *mm, struct task_struct *p, struct user_namespace *user_ns) {
    int err;

    /* Initialize memory mappings */
    mm->mmap = NULL;
    mm->mmap_cache = NULL;
    mm->get_unmapped_area = arch_get_unmapped_area;
    mm->unmap_area = arch_unmap_area;

    /* Initialize reference counts */
    atomic_set(&mm->count, 1);
    atomic_set(&mm->mmo_count, 0);
    atomic_set(&mm->page_table_count, 0);

    /* Initialize locks */
    spin_lock_init(&mm->page_table_lock);
    spin_lock_init(&mm->mmap_lock);

    /* Set up flags based on the current process's memory management state */
    if (current->mm) {
        mm->flags = current->mm->flags & ~MMF_INIT;
    } else {
        mm->flags = 0;
    }

    /* Allocate page tables */
    err = allocate_page_tables(mm);
    if (err) {
        return NULL;
    }

    /* Initialize new context for the task */
    err = init_new_context(p, mm);
    if (err) {
        free_page_tables(mm);
        return NULL;
    }

    mm->user_ns = get_user_namespace(user_ns);

    return mm;
}

