struct mm_struct *init_new_context(struct task_struct *p, struct user_namespace *user_ns) {
    struct mm_struct *mm;

    mm = kzalloc(sizeof(*mm), GFP_KERNEL);
    if (!mm)
        return NULL;

    atomic_set(&mm->mm_users, 1);
    atomic_set(&mm->mm_count, 1);
    mm->mmap = NULL;
    mm->mmap_max = 0;
    mm->start_code = 0;
    mm->end_code = 0;
    mm->start_data = 0;
    mm->end_data = 0;
    mm->start_brk = 0;
    mm->brk = 0;
    mm->start_stack = 0;
    mm->arg_start = 0;
    mm->arg_end = 0;
    mm->env_start = 0;
    mm->env_end = 0;
    mm->saved_auxv = NULL;
    mm->def_flags = 0;
    mm->flags = 0;
    mm->user_namespace = get_user_ns(user_ns);

    if (current->mm) {
        mm->def_flags = current->mm->def_flags;
    }

    if (init_new_context_pgd(mm)) {
        put_user_ns(mm->user_namespace);
        kfree(mm);
        return NULL;
    }

    return mm;
}
